select case when duration_sec >= 510 then 'high' when duration_sec >= 95 then 'mid' else 'low' end as duration_sec_bucket, hour(event_time) as event_hour, min(event_time) as first_event_time, sum(duration_sec) as total_duration_sec, max(duration_sec) as max_duration_sec from web_events where event_time >= '2025-09-05' and duration_sec = 159 group by rollup(case when duration_sec >= 510 then 'high' when duration_sec >= 95 then 'mid' else 'low' end, hour(event_time)) order by first_event_time desc
